describe('Numeric Column Summary Row', () => {
  beforeEach(() => {
    cy.visit('/table');
  });

  it('should display summary row with correct total when table is populated', () => {
    // Intercept the API call to fetch table data
    cy.intercept('GET', '/api/table/data').as('getTableData');
    cy.get('[data-testid="load-table-button"]').click();

    // Wait for the API response
    cy.wait('@getTableData');

    // Verify table rows are displayed
    cy.get('[data-testid="table-row"]').should('have.length.greaterThan', 0);

    // Verify numeric column exists
    cy.get('[data-testid="numeric-column"]').should('be.visible');

    // Verify summary row is visible at the bottom
    cy.get('[data-testid="summary-row"]').should('be.visible');

    // Verify summary row contains total
    cy.get('[data-testid="summary-total"]').should('contain', 'Total');

    // Verify total value is calculated correctly (e.g., 10 + 20 + 5 = 35)
    cy.get('[data-testid="summary-value"]').should('contain', '35');

    // Verify summary row is styled as a footer
    cy.get('[data-testid="summary-row"]').should('have.class', 'table-footer');
  });

  it('should handle empty table and display appropriate message', () => {
    // Intercept the API call with empty data
    cy.intercept('GET', '/api/table/data', {
      statusCode: 200,
      body: { rows: [] }
    }).as('getEmptyTableData');

    cy.get('[data-testid="load-table-button"]').click();
    cy.wait('@getEmptyTableData');

    // Verify table is empty
    cy.get('[data-testid="table-row"]').should('not.exist');

    // Verify summary row is not displayed or shows zero
    cy.get('[data-testid="summary-row"]').should('be.visible');
    cy.get('[data-testid="summary-total"]').should('contain', 'Total');
    cy.get('[data-testid="summary-value"]').should('contain', '0');

    // Verify empty state message is shown
    cy.get('[data-testid="empty-table-message"]').should('be.visible');
    cy.get('[data-testid="empty-table-message"]').should('contain', 'No data available');
  });
});
